// "Préparer les 3 publications" — détermine, pour la semaine en cours, la famille/variante de
// gabarit à utiliser sur chacun des 3 créneaux pilotés (lundi, mercredi, vendredi), avec rotation
// hebdomadaire par famille pour respecter "ça doit varier selon le sujet" (au lieu d'une matrice
// unique lundi/vendredi comme envisagé initialement, voir DOCUMENTATION.md).
//
// Chaque créneau a un angle fixe (lundi = Le Déclic, mercredi = Savoir-Faire, vendredi =
// L'Ancrage) mais la variante utilisée à l'intérieur de cet angle tourne semaine après semaine,
// parmi les seules variantes déjà dessinées dans Figma (le pool s'enrichit au fur et à mesure que
// de nouveaux gabarits sont maquettés).

function nextWeekday(targetIsoWeekday, hour) {
  const now = new Date();
  const currentIso = now.getUTCDay() === 0 ? 7 : now.getUTCDay();
  let diff = targetIsoWeekday - currentIso;
  if (diff <= 0) diff += 7;
  const result = new Date(now);
  result.setUTCDate(now.getUTCDate() + diff);
  result.setUTCHours(hour, 0, 0, 0);
  return result.toISOString();
}

// Pools de variantes disponibles par famille — n'y figurent que les gabarits déjà dessinés et
// câblés dans render-service/layouts.js. Ajouter une entrée ici dès qu'une nouvelle variante
// (Décoration, Salle, Savoir-Faire Traiteur...) est maquettée et intégrée.
const POOLS = {
  declic: ["eventplanning", "traiteur"],
  savoirfaire: ["generique", "chiffre", "traiteur"],
  ancrage: ["a", "b"]
};

const SLOTS = [
  { jour: "Lundi", weekday: 1, famille: "declic" },
  { jour: "Mercredi", weekday: 3, famille: "savoirfaire" },
  { jour: "Vendredi", weekday: 5, famille: "ancrage" }
];

// Données statiques du workflow n8n : un index de rotation par famille, qui persiste d'une
// exécution hebdomadaire à l'autre (équivalent de $getWorkflowStaticData('global') dans un nœud
// Code n8n réel — représenté ici comme un objet passé/retourné pour rester testable hors n8n).
const state = $getWorkflowStaticData("global");
if (!state.rotation) state.rotation = { declic: 0, savoirfaire: 0, ancrage: 0 };

const items = SLOTS.map(slot => {
  const pool = POOLS[slot.famille];
  const idx = state.rotation[slot.famille] % pool.length;
  const variante = pool[idx];
  state.rotation[slot.famille] = idx + 1;
  return {
    json: {
      jour: slot.jour,
      famille: slot.famille,
      variante,
      attempt: 1,
      modification_feedback: "",
      target_due_at: nextWeekday(slot.weekday, 8)
    }
  };
});

return items;

// "Préparer le Prompt Claude" (mode n8n : runOnceForEachItem)
// Construit le system prompt + le schéma JSON attendu pour le créneau du jour (jour / famille /
// variante, déterminés par code_prepare_pilliers.js), à partir de la charte éditoriale et du
// brief créa validés avec le cabinet.

const d = $json;
const attempt = d.attempt || 1;
const isRetry = attempt > 1;

// ---------------------------------------------------------------------------------------------
// Faits de marque vérifiés (site tera.events, réseaux, échanges avec le cabinet) — jamais à
// réinventer, jamais à approximer. Toute donnée chiffrée utilisée dans un texte doit venir d'ici.
// ---------------------------------------------------------------------------------------------
const FAITS_TERA = `
- TERA EVENTS, agence d'event planning à Cocody 2 Plateaux, Abidjan, Côte d'Ivoire.
- 4+ années d'activité, 100+ événements organisés, 100% de satisfaction client affichée.
- Salle événementielle modulable de 150 m², son/lumière/climatisation inclus.
- Les tarifs traiteur sont ceux des formules TERA EVENTS : cocktail dînatoire à partir de
  10 500 F CFA/personne et repas assis, en buffet ou avec service à table, à partir de
  19 000 F CFA/personne. L'option boissons coûte 3 500 F CFA/personne. Les tarifs sont dégressifs
  à partir de 100 personnes et le service traiteur indépendant est proposé dès 30 personnes.
- Cocktails dînatoires TERA EVENTS : Découverte (8 à 10 choix), Événement (10 à 12 choix) et
  Prestige (12 à 15 choix).
- Repas assis TERA EVENTS : Rapide, L'Essentiel, Prestige et Gala. La formule Gala compte
  9 services. Les serveurs et soft drinks sont inclus dans les formules de repas assis.
- Formules Event Planning : coordination complète, coordination partielle, coordination Jour J
  seul. Devis gratuit sous 48h après premier contact.
- Contact : +225 05 66 22 10 10, reservations@tera.events, tera.events
- Spécialités locales fréquemment citées : tchep, yassa, attiéké, alloco, cuisine ivoirienne et
  internationale.
`.trim();

// ---------------------------------------------------------------------------------------------
// Charte éditoriale — deux règles absolues, non négociables, rappelées par le cabinet à plusieurs
// reprises. Elles priment sur toute autre considération de style.
// ---------------------------------------------------------------------------------------------
const CHARTE = `
Tu es la personne qui rédige pour TERA EVENTS sur les réseaux sociaux : quelqu'un qui connaît le
métier de l'intérieur (organisation d'événements à Abidjan), pas un rédacteur générique.

RÈGLE ABSOLUE N°1 — ÉCRITURE HUMAINE, AUCUNE TRACE D'IA :
- Interdiction absolue d'utiliser un tiret cadratin ou demi-cadratin ("—" ou "–") comme
  ponctuation stylistique au milieu d'une phrase : c'est immédiatement reconnaissable comme un
  texte généré par une IA. Utilise une virgule, un point, des parenthèses, ou reformule en deux
  phrases courtes. Le trait d'union normal dans un mot composé reste autorisé.
- Interdiction des tics de rédaction IA reconnaissables entre mille : "plongeons dans", "dans un
  monde où", "il est essentiel/crucial de", "n'hésitez pas à", "que vous soyez X ou Y", les
  triplets parfaitement symétriques ("rapide, fiable et élégant"), les superlatifs creux utilisés
  par réflexe plutôt que pour un fait précis ("unique", "exceptionnel", "incroyable").
- Ne jamais résumer ou reformuler ce qu'on vient de dire en fin de texte ("en résumé", "bref",
  "vous l'aurez compris").
- Varie réellement la longueur et la construction des phrases. Une phrase courte peut suivre une
  phrase longue. Une idée n'a pas besoin d'être immédiatement rééquilibrée par une proposition
  symétrique.
- Avant de répondre, relis-toi mentalement : si une phrase pourrait sortir de n'importe quelle
  agence événementielle dans n'importe quel pays, réécris-la ou supprime-la. Le texte doit sentir
  Abidjan, TERA, et une personne précise qui l'a écrit.

RÈGLE ABSOLUE N°2 — ORTHOGRAPHE ET GRAMMAIRE IRRÉPROCHABLES :
- Français impeccable : accords en genre et en nombre, conjugaisons correctes, ponctuation
  française correcte (espace avant : ; ! ? et après «, avant »).
- Aucune faute n'est tolérée, même mineure. Relis-toi avant de répondre.

RIGUEUR FACTUELLE :
- N'avance jamais un chiffre, un prix ou un délai qui ne figure pas explicitement dans les faits
  TERA ci-dessous. Si tu as besoin d'un chiffre et qu'aucun ne correspond dans les faits fournis,
  reformule sans chiffre plutôt que d'en inventer un.
- Tout prix traiteur doit être clairement présenté comme le tarif d'une formule TERA EVENTS, et
  non comme un prix moyen du marché ou une recommandation générale.
- Ne cite jamais le prénom, le nom ou la fonction nominative d'un membre de l'équipe. Utilise
  uniquement « notre équipe », « nos chefs », « nos serveurs » ou « notre équipe de coordination ».

TON DE MARQUE :
- Chaleureux, précis, sensoriel (matières, lumière, ambiance) plutôt que des superlatifs vides.
- Toujours une raison concrète d'écrire à la fin du texte, jamais un simple "suivez-nous".
- Ancrage local assumé : saisons ivoiriennes, quartiers d'Abidjan, spécialités locales, F CFA sans
  détour.
- On évite de cacher le prix par réflexe : la transparence rassure plus qu'elle ne dévalorise.

FAITS TERA EVENTS (seule source pour tout chiffre, prix, délai ou nom cité) :
${FAITS_TERA}
`.trim();

// ---------------------------------------------------------------------------------------------
// Schémas par famille × variante. Les champs listés ici sont exactement ceux attendus par
// render-service/layouts.js — ne pas en ajouter ni en renommer sans mettre à jour ce fichier ET
// layouts.js en parallèle. Les éléments de marque fixes (tags de catégorie, coordonnées, CTA
// visuel statique) ne sont PAS demandés à Claude : ils sont injectés tels quels au moment du
// rendu (voir code_prepare_visuals.js), pour ne jamais risquer une erreur sur une donnée de
// marque.
// ---------------------------------------------------------------------------------------------

const SCHEMAS = {
  "declic:traiteur": {
    angle: "Le Déclic — Traiteur : lever une objection ou une question fréquente sur le traiteur (prix, format, personnalisation), avec la vraie réponse chiffrée.",
    schema: `{
  "slides": [{
    "accroche": "Amorce manuscrite courte (4-6 mots), ex. 'Ce que ça inclut vraiment'",
    "titre": "2-3 mots, le format concerné : 'En cocktail' ou 'En buffet' ou 'En dîner assis'",
    "texte": "1 phrase, ce que ce format inclut concrètement (18-25 mots)",
    "prix": "Le prix exact correspondant, tiré des faits TERA, format '10 500' ou '19 000' (sans F CFA, juste le nombre)"
  }],
  "caption": "Légende complète du post (300-450 caractères, 2-3 paragraphes courts), qui développe le sujet et se termine par une invitation concrète à écrire",
  "hashtags": ["5 à 8 hashtags", "mélange marque/local/expertise"]
}`
  },

  "declic:eventplanning": {
    angle: "Le Déclic — Event Planning : un carrousel de 5 slides qui lève une objection ou explique une formule de coordination, avec une couverture forte et une conclusion qui invite à demander un devis.",
    schema: `{
  "slides": [
    { "titre_normal": "Première partie du titre de couverture (2-4 mots)", "titre_accent": "Partie accentuée du titre (1-3 mots)" },
    { "tag_formule": "3-4 mots MAJUSCULES", "titre_normal": "Première partie du titre", "titre_accent": "Partie accentuée du titre", "texte": "1-2 phrases (25-40 mots)" },
    { "tag_formule": "3-4 mots MAJUSCULES", "titre_normal": "Première partie du titre", "titre_accent": "Partie accentuée du titre", "texte": "1-2 phrases (25-40 mots)" },
    { "tag_formule": "3-4 mots MAJUSCULES", "titre_normal": "Première partie du titre", "titre_accent": "Partie accentuée du titre", "texte": "1-2 phrases (25-40 mots)" },
    { "tag_formule": "3-4 mots MAJUSCULES pour la conclusion", "titre_normal": "Première partie du titre de conclusion", "titre_accent": "Partie accentuée du titre", "texte": "1-2 phrases de synthèse (20-30 mots)", "cta_label": "3-5 mots MAJUSCULES, ex. 'DEMANDEZ VOTRE DEVIS'" }
  ],
  "caption": "Légende complète du post (300-450 caractères), qui pose le sujet du carrousel et se termine par une invitation concrète",
  "hashtags": ["5 à 8 hashtags", "mélange marque/local/expertise"]
}`
  },

  "savoirfaire:generique": {
    angle: "Le conseil du mercredi : un carrousel pratique de 4 slides, un conseil concret applicable par n'importe quel client TERA (traiteur, décoration ou event planning), pas une leçon abstraite.",
    schema: `{
  "slides": [
    { "repere": "Court repère numéroté, ex. '01 — L'arrivée'", "titre": "Une phrase-titre marquante (10-16 mots)", "texte": "1-2 phrases concrètes et actionnables (20-35 mots)" },
    { "repere": "...", "titre": "...", "texte": "..." },
    { "repere": "...", "titre": "...", "texte": "..." },
    { "repere": "Repère de conclusion", "titre": "Titre de conclusion", "conclusion": "1 phrase de clôture (15-25 mots)", "cta_question": "Une question courte (5-8 mots)", "cta_action": "2-3 mots MAJUSCULES, ex. 'ON EN PARLE'" }
  ],
  "caption": "Légende complète du post (300-450 caractères)",
  "hashtags": ["5 à 8 hashtags", "mélange marque/local/expertise"]
}`
  },

  "savoirfaire:chiffre": {
    angle: "Le chiffre du mercredi : un carrousel fixe de 5 slides construit autour d'UN SEUL chiffre ou délai réel de TERA (jamais une statistique externe non vérifiée) : accroche chiffrée, développement, 3 principes numérotés, 3 points pratiques, conclusion + question.",
    schema: `{
  "slides": [
    { "chiffre": "Le chiffre en gros caractères, ex. '48' (nombre seul, sans unité)", "unite": "L'unité en 1 mot, ex. 'heures'", "headline": "Ce que ce chiffre permet (8-12 mots)", "insight": "1 phrase qui explique pourquoi ça compte (12-20 mots)" },
    { "surtitre": "3-5 mots MAJUSCULES", "statistique": "Reformulation courte du même chiffre ou d'un angle complémentaire", "cartouche": "2-4 mots, un label court", "titre": "Titre développé (8-14 mots)", "texte": "1-2 phrases (20-30 mots)" },
    { "surtitre": "Une formule courte en 4-7 mots", "titre": "Titre (5-9 mots)", "conseil1_titre": "Question courte", "conseil1_texte": "1 principe concret (8-15 mots)", "conseil2_titre": "Question courte", "conseil2_texte": "1 principe concret (8-15 mots)", "conseil3_titre": "Question courte", "conseil3_texte": "1 principe concret (8-15 mots)" },
    { "surtitre": "Une formule courte en 4-7 mots", "titre": "Titre (5-9 mots)", "detail1": "1 point pratique court (5-9 mots)", "detail2": "1 point pratique court (5-9 mots)", "detail3": "1 point pratique court (5-9 mots)", "conclusion": "1 phrase de clôture courte (6-10 mots)" },
    { "badge": "1-2 mots", "titre": "Titre de conclusion (8-12 mots)", "texte": "1 phrase (15-25 mots)", "cta_question": "Question courte (3-6 mots)", "cta_action": "2-3 mots MAJUSCULES avec une flèche finale" }
  ],
  "caption": "Légende complète du post (300-450 caractères)",
  "hashtags": ["5 à 8 hashtags", "mélange marque/local/expertise"]
}`
  },
  "savoirfaire:traiteur": {
    angle: "Le Savoir-Faire Traiteur : présenter clairement les différentes gammes TERA, leurs usages et les critères concrets pour choisir selon le format de l'événement.",
    schema: `{
  "slides": [
    { "badge1": "4-6 mots, ex. 'Des gammes Découverte à Gala'", "badge2": "4-6 mots, ex. 'Comment choisir le bon menu'", "texte": "Phrase d'introduction courte et concrète (15-25 mots)" },
    { "gamme_ligne1": "GAMME", "gamme_ligne2": "DÉCOUVERTE", "badge": "2-4 mots", "texte": "Description claire de la gamme (20-35 mots)" },
    { "gamme_ligne1": "GAMME", "gamme_ligne2": "PRESTIGE", "badge": "2-4 mots", "texte": "Description claire de la gamme (20-35 mots)" },
    { "gamme_ligne1": "GAMME", "gamme_ligne2": "GALA", "badge": "2-4 mots", "texte": "Description claire de la gamme (20-35 mots)" },
    { "gamme_ligne1": "COMMENT", "gamme_ligne2": "CHOISIR ?", "badge": "2-4 mots", "texte": "Conseil de choix et invitation à demander un devis (20-35 mots)" }
  ],
  "caption": "Légende complète du post (300-450 caractères), concrète et orientée vers la demande de devis",
  "hashtags": ["5 à 8 hashtags", "mélange marque/local/expertise"]
}`
  },

  "ancrage:a": {
    angle: "L'Ancrage du vendredi : une citation courte et marquante, ancrée dans la saison ou le calendrier ivoirien du moment (voir la ligne éditoriale pour le calendrier culturel), qui projette le lecteur dans son propre événement.",
    schema: `{
  "slides": [{
    "citation_accent": "L’accroche saisonnière ou le moment clé en 2-5 mots, par exemple 'Rentrée corporate :'",
    "citation_main": "La suite de la citation en 12-22 mots, concrète et directement liée à l’événement"
  }],
  "caption": "Légende complète du post (250-400 caractères)",
  "hashtags": ["5 à 8 hashtags", "mélange marque/local/saisonnier"]
}`
  },

  "ancrage:b": {
    angle: "L'Ancrage du vendredi : un message plus direct que la citation, avec un vrai appel à l'action visible, toujours ancré dans la saison ou le calendrier ivoirien du moment.",
    schema: `{
  "slides": [{
    "headline": "Titre fort (10-16 mots), ancré dans une saison ou un moment ivoirien précis",
    "body": "1 phrase d'appui (15-25 mots)"
  }],
  "caption": "Légende complète du post (250-400 caractères)",
  "hashtags": ["5 à 8 hashtags", "mélange marque/local/saisonnier"]
}`
  }
};

const key = `${d.famille}:${d.variante}`;
const config = SCHEMAS[key];
if (!config) {
  throw new Error(`Aucun schéma défini pour famille="${d.famille}" variante="${d.variante}". Vérifie code_prepare_pilliers.js et SCHEMAS dans ce fichier.`);
}

const retryNote = isRetry
  ? ` Ceci est une nouvelle tentative (proposition n°${attempt}) : une première version n'a pas été validée par le cabinet${d.modification_feedback ? `, avec ce retour : "${d.modification_feedback}"` : ""}. Corrige en conséquence tout en respectant strictement la charte.`
  : "";

const systemPrompt = `${CHARTE}

Aujourd'hui : ${d.jour}. Angle : ${config.angle}

Tu dois répondre UNIQUEMENT avec un objet JSON valide, sans texte avant ni après, sans balises
markdown, respectant exactement ce schéma :
${config.schema}

RAPPEL : ta toute dernière réponse ne doit contenir STRICTEMENT RIEN d'autre que l'objet JSON. Le
premier caractère de ta réponse doit être { et le dernier doit être }.`;

const userPrompt = `Rédige la publication du ${d.jour.toLowerCase()} pour TERA EVENTS, sur l'angle "${config.angle}".${retryNote} Choisis un sujet précis et concret, pas un thème générique.`;

return {
  json: {
    ...d,
    anthropic_request: {
      model: "claude-sonnet-5",
      max_tokens: 8000,
      system: systemPrompt,
      messages: [{ role: "user", content: userPrompt }]
    }
  }
};

// n8n node mode: runOnceForEachItem (this file must return a single {json:{...}} object, not an array)
// Reprend telle quelle la double sécurité anti-crash de La Lignée : le nœud ne doit jamais
// planter même si Claude répond avec du texte non conforme (préambule, balises markdown).
const contentBlocks = $json.content || [];
const textBlocks = contentBlocks.filter(b => b.type === "text");
const raw = textBlocks.length ? textBlocks.map(b => b.text).join("") : undefined;

function tryParse(text) {
  if (!text) return undefined;
  try {
    return JSON.parse(text);
  } catch (e) {
    return undefined;
  }
}

let parsed = tryParse(raw);
if (parsed === undefined) {
  const match = raw && raw.match(/\{[\s\S]*\}/);
  parsed = match ? tryParse(match[0]) : undefined;
}
if (parsed === undefined) {
  parsed = { error: "Parsing JSON échoué", raw: raw || JSON.stringify($json) };
}

const source = $("Préparer le Prompt Claude").item.json;

return {
  json: {
    jour: source.jour,
    famille: source.famille,
    variante: source.variante,
    attempt: source.attempt || 1,
    target_due_at: source.target_due_at,
    ...parsed
  }
};

// Prépare une photo de fond contextuelle. L'IA ne produit aucun texte ni élément graphique :
// ceux-ci restent exclusivement gérés par les gabarits Figma du render-service.
const d = $json;
const content = JSON.stringify(d.slides || []).slice(0, 5000);
const prompt = `Luxury event editorial photography in Abidjan, Côte d'Ivoire, created as a background for a TERA EVENTS social-media design. Subject and intent: ${content}. Show a credible high-end event scene related to event planning, catering, decoration or an event venue. If people appear, every person must be Black African, with natural Ivorian or West African appearance. Refined navy blue, warm blush and neutral tones, cinematic lighting, realistic professional photography, premium but welcoming atmosphere. Leave calm visual space for overlaid typography. Absolutely no readable text, letters, numbers, logos, watermarks, signage or invented branding. Square composition with safe central crop.`;

return {
  json: {
    gemini_request: {
      contents: [{ parts: [{ text: prompt }] }],
      generationConfig: { responseModalities: ["IMAGE"] }
    }
  }
};

// Réassocie la réponse image au contenu éditorial avant le rendu Figma.
const source = $("Parser Réponse Claude").item.json;
const parts = $json.candidates?.[0]?.content?.parts || [];
const imagePart = parts.find(part => part.inlineData?.data || part.inline_data?.data);
const inline = imagePart?.inlineData || imagePart?.inline_data;

if (!inline?.data) {
  throw new Error("La génération de la photo de fond n'a retourné aucune image exploitable.");
}

return {
  json: {
    ...source,
    background_image: `data:${inline.mimeType || inline.mime_type || "image/png"};base64,${inline.data}`
  }
};

// "Préparer Requêtes Visuel" — transforme le JSON rédigé par Claude (slides + caption +
// hashtags) en une liste d'appels au render-service, un par slide/gabarit. Injecte ici les
// éléments de marque fixes (tags de catégorie, coordonnées, CTA visuel statique) que Claude ne
// génère jamais, pour ne courir aucun risque d'erreur sur une donnée de marque.
//
// IMPORTANT : les noms de champs ci-dessous doivent correspondre exactement à ceux attendus par
// render-service/layouts.js. Toute évolution d'un gabarit doit être répercutée aux deux endroits.

const d = $json;

const TEMPLATE_MAP = {
  "declic:traiteur": ["tera-declic-traiteur"],
  "declic:eventplanning": [
    "tera-declic-eventplanning-s1",
    "tera-declic-eventplanning-s2",
    "tera-declic-eventplanning-s3",
    "tera-declic-eventplanning-s4",
    "tera-declic-eventplanning-s5"
  ],
  "savoirfaire:generique": [
    "tera-savoirfairemercredi-s1",
    "tera-savoirfairemercredi-s2",
    "tera-savoirfairemercredi-s3",
    "tera-savoirfairemercredi-s4"
  ],
  "savoirfaire:chiffre": [
    "tera-chiffremercredi-s1",
    "tera-chiffremercredi-s2",
    "tera-chiffremercredi-s3",
    "tera-chiffremercredi-s4",
    "tera-chiffremercredi-s5"
  ],
  "savoirfaire:traiteur": [
    "tera-savoirfairetraiteur-s1",
    "tera-savoirfairetraiteur-s2",
    "tera-savoirfairetraiteur-s3",
    "tera-savoirfairetraiteur-s4",
    "tera-savoirfairetraiteur-s5"
  ],
  "ancrage:a": ["tera-ancragevendredi-a"],
  "ancrage:b": ["tera-ancragevendredi-b"]
};

// Champs de marque fixes, injectés à chaque appel de la famille/variante correspondante — jamais
// laissés à la charge de Claude.
const STATIC_FIELDS = {
  "declic:traiteur": { tag: "LE DÉCLIC · TRAITEUR", devise: "FCFA" },
  "declic:eventplanning": { tag: "LE DÉCLIC · EVENT PLANNING" },
  "savoirfaire:generique": {},
  "savoirfaire:chiffre": { edition_label: "Le chiffre du mercredi" },
  "savoirfaire:traiteur": {},
  "ancrage:a": { tag: "L'ANCRAGE DU VENDREDI" },
  "ancrage:b": { tag: "L'ANCRAGE DU VENDREDI", cta_label: "Demander un devis →" }
};

const key = `${d.famille}:${d.variante}`;
const templates = TEMPLATE_MAP[key];
if (!templates) {
  throw new Error(`Aucun gabarit défini pour famille="${d.famille}" variante="${d.variante}".`);
}

const slides = Array.isArray(d.slides) ? d.slides : [];
const hashtagsText = Array.isArray(d.hashtags) ? d.hashtags.join(" ") : (d.hashtags || "");
const caption = [d.caption, hashtagsText].filter(Boolean).join("\n\n");
const postId = $execution.id + "-" + d.jour;
const backgroundImages = Array.isArray(d.background_images) ? d.background_images : [];

const results = templates.map((template, idx) => {
  const slideFields = slides[idx] || {};
  // L'image est choisie en amont dans la banque média, indépendamment de la rédaction Claude.
  // Une image propre à la slide est prioritaire, puis celle de la liste du carrousel, puis le
  // fond commun de la publication. Sans image fournie, le fond Figma canonique reste le fallback.
  const backgroundImage = slideFields.background_image || backgroundImages[idx] || d.background_image;
  const backgroundPosition = slideFields.background_position || d.background_position;
  return {
    json: {
      post_id: postId,
      jour: d.jour,
      famille: d.famille,
      variante: d.variante,
      template,
      slide_index: idx + 1,
      slide_count: templates.length,
      target_due_at: d.target_due_at,
      render_body: {
        ...STATIC_FIELDS[key],
        ...slideFields,
        ...(backgroundImage ? { background_image: backgroundImage } : {}),
        ...(backgroundPosition ? { background_position: backgroundPosition } : {})
      },
      caption
    }
  };
});

return results;

// "Préparer Pack Hebdomadaire" — regroupe les publications des 3 créneaux de la semaine (lundi,
// mercredi, vendredi) et construit le formulaire de validation groupé, sur le modèle éprouvé de
// La Lignée (code_hebdo_prepare_pack.js) : un seul geste de validation le dimanche plutôt que 3
// validations séparées dans la semaine.

function escapeHtml(str) {
  if (str === undefined || str === null) return "";
  return String(str)
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;")
    .replace(/'/g, "&#039;")
    .replace(/\n/g, "<br>");
}

// Les gabarits TERA n'ont pas de champ "titre" unique et commun (titre/headline/citation/chiffre
// selon la famille) — on prend le premier qui existe pour l'aperçu du pack.
function titleFor(renderBody) {
  return renderBody.titre || renderBody.headline || renderBody.citation || renderBody.chiffre || "";
}

const items = $input.all();
const byJour = {};
items.forEach(it => {
  const j = it.json.jour;
  if (!byJour[j]) byJour[j] = [];
  byJour[j].push(it.json);
});

const jourOrder = ["Lundi", "Mercredi", "Vendredi"];

const slots = jourOrder
  .filter(j => byJour[j])
  .map(jour => {
    const group = byJour[jour].sort((a, b) => (a.slide_index || 1) - (b.slide_index || 1));
    const hero = group.find(g => g.slide_index === 1) || group[0];
    const caption = group[0].caption;
    const rawTitle = titleFor(hero.render_body || {});
    // Une génération dont la réponse Claude n'a pas pu être parsée dégrade gracieusement en amont
    // plutôt que de planter, mais laisse ce créneau sans titre ni légende — à signaler clairement
    // ici plutôt que d'afficher un aperçu vide sans explication.
    const looksFailed = !caption && !rawTitle;
    const titleText = rawTitle || `${jour} — ${group[0].famille}/${group[0].variante}`;
    return {
      jour,
      famille: group[0].famille,
      variante: group[0].variante,
      heroImageUrl: hero.url,
      titleText,
      caption,
      looksFailed,
      renderItems: group
    };
  });

const fields = [];
slots.forEach(s => {
  const warningBanner = s.looksFailed
    ? `<p style="color:#b00; font-weight:bold;">⚠️ La génération a échoué pour cette publication (réponse non exploitable). Choisissez "Modifier" pour la régénérer automatiquement, un commentaire n'est pas nécessaire.</p>`
    : "";
  fields.push({
    fieldLabel: " ",
    fieldType: "html",
    html: `<h3>${escapeHtml(s.jour)} — ${escapeHtml(s.famille)} / ${escapeHtml(s.variante)}</h3>${warningBanner}<img src="${s.heroImageUrl}" style="max-width:320px;border-radius:8px" /><p><b>${escapeHtml(s.titleText)}</b></p><p>${escapeHtml(s.caption)}</p>`
  });
  fields.push({
    fieldLabel: `${s.jour} — décision`,
    fieldType: "dropdown",
    fieldOptions: { values: [{ option: "Valider" }, { option: "Modifier" }, { option: "Refuser" }] },
    requiredField: true
  });
  fields.push({
    fieldLabel: `${s.jour} — Commentaire (si Modifier)`,
    fieldType: "textarea",
    requiredField: false
  });
});

return [{
  json: {
    slots,
    formFieldsJson: JSON.stringify(fields, null, 2)
  }
}];

// "Traiter la Validation Hebdomadaire" — répartit les décisions du formulaire de validation
// (une ligne Valider/Modifier/Refuser + commentaire par créneau) vers les branches de routage.

const formData = $("Envoyer Pack de Validation").item.json.data;
const slots = $("Préparer Pack Hebdomadaire").item.json.slots;
const pilierConfig = $("Préparer les 3 publications").all().map(i => i.json);

const results = [];
slots.forEach(s => {
  const decision = formData[`${s.jour} — décision`];
  const commentaire = formData[`${s.jour} — Commentaire (si Modifier)`] || "";
  const config = pilierConfig.find(c => c.jour === s.jour) || {};
  results.push({
    json: {
      jour: s.jour,
      famille: s.famille,
      variante: s.variante,
      attempt: config.attempt || 1,
      target_due_at: config.target_due_at,
      decision,
      commentaire,
      renderItems: s.renderItems
    }
  });
});

return results;

// "Préparer Buffer" — transforme une publication validée en requête de programmation.
// Les identifiants de canaux sont lus depuis l'environnement n8n, jamais écrits dans le code.

const d = $json;
if (d.decision !== "Valider") return [];

const CHANNELS = {
  facebook: $env.BUFFER_CHANNEL_FACEBOOK,
  instagram: $env.BUFFER_CHANNEL_INSTAGRAM,
  linkedin: $env.BUFFER_CHANNEL_LINKEDIN
};

const missing = Object.entries(CHANNELS)
  .filter(([, value]) => !value)
  .map(([name]) => name);

if (missing.length) {
  throw new Error(`Canaux Buffer manquants : ${missing.join(", ")}. Renseigne les variables BUFFER_CHANNEL_* dans l'environnement n8n.`);
}

const renderItems = Array.isArray(d.renderItems) ? d.renderItems : [];
const media = renderItems
  .sort((a, b) => (a.slide_index || 1) - (b.slide_index || 1))
  .map(item => item.url)
  .filter(Boolean);

if (!media.length) throw new Error(`Aucun visuel rendu pour la publication du ${d.jour}.`);

const caption = renderItems[0]?.caption || d.caption || "";
if (!caption) throw new Error(`Aucune légende disponible pour la publication du ${d.jour}.`);

const mutation = `mutation CreatePost($input: CreatePostInput!) {
  createPost(input: $input) {
    ... on PostActionSuccess { post { id text dueAt } }
    ... on MutationError { message }
  }
}`;

return Object.entries(CHANNELS).map(([network, channelId]) => ({
  json: {
    post_id: renderItems[0]?.post_id,
    jour: d.jour,
    network,
    channel_id: channelId,
    due_at: d.target_due_at,
    text: caption,
    media,
    status: "pending_buffer",
    graphql_body: {
      query: mutation,
      variables: {
        input: {
          text: caption,
          channelId,
          assets: media.map(url => ({ image: { url } })),
          schedulingType: "automatic",
          mode: "customScheduled",
          dueAt: d.target_due_at,
          ...(network === "facebook" ? { metadata: { facebook: { type: "post" } } } : {}),
          ...(network === "instagram" ? { metadata: { instagram: { type: "post", shouldShareToFeed: true } } } : {})
        }
      }
    }
  }
}));

// n8n node mode: runOnceForEachItem
// Buffer peut renvoyer une erreur métier dans une réponse HTTP 200. Sans ce contrôle, n8n
// considère à tort la programmation comme réussie.
const response = $json;
const result = response?.data?.createPost;

if (!result) {
  throw new Error("Buffer n'a renvoyé aucun résultat createPost.");
}

if (result.message) {
  throw new Error(`Buffer a refusé la programmation : ${result.message}`);
}

if (!result.post?.id) {
  throw new Error("Buffer n'a créé aucune publication et n'a fourni aucun identifiant.");
}

return {
  json: {
    buffer_post_id: result.post.id,
    due_at: result.post.dueAt,
    status: "scheduled"
  }
};

// "Préparer Régénération" — renvoie les publications à modifier vers la préparation du prompt.
// Le commentaire humain est prioritaire ; en cas d'échec technique, une consigne neutre suffit.

const d = $json;
if (d.decision !== "Modifier") return [];

const attempt = Number(d.attempt || 1) + 1;
const maxAttempts = 3;
if (attempt > maxAttempts) {
  throw new Error(`Nombre maximal de régénérations atteint pour ${d.jour}. Une intervention humaine est nécessaire.`);
}

const feedback = String(d.commentaire || "").trim() ||
  "La proposition précédente n'était pas exploitable. Reprends entièrement le contenu en respectant le schéma JSON, la ligne éditoriale et les faits TERA.";

return [{
  json: {
    jour: d.jour,
    famille: d.famille,
    variante: d.variante,
    target_due_at: d.target_due_at,
    attempt,
    modification_feedback: feedback,
    previous_render_items: d.renderItems || []
  }
}];
